N=/workspace/nox
echo "== results"; cat $N/state/p3/img_test2.txt | cut -c1-330; echo "== core log"; tail -n 6 $N/agent/out/k_rs2_bg.log | cut -c1-200
echo "== models present"; find $N/models /workspace -maxdepth 5 \( -iname "*flux*" -o -iname "ae.safetensors" -o -iname "*t5xxl*" -o -iname "clip_l*" -o -iname "*nsfw*" -o -iname "*age*classif*" -o -iname "*chroma*" \) -not -path "*/venv/*" -not -path "*/node_modules/*" 2>/dev/null | head -20 | while read f; do echo "$(du -h "$f" 2>/dev/null | cut -f1) $f"; done
echo "== disk"; df -h /workspace | tail -1; echo "== HF reach"; curl -s -m 10 -o /dev/null -w "hf %{http_code}\n" https://huggingface.co/leejet/FLUX.1-schnell-gguf/resolve/main/README.md; curl -s -m 10 -I https://huggingface.co/leejet/FLUX.1-schnell-gguf/resolve/main/flux1-schnell-q4_0.gguf | head -1; curl -s -m 10 -I https://huggingface.co/black-forest-labs/FLUX.1-schnell/resolve/main/ae.safetensors | head -1; curl -s -m 10 -I https://huggingface.co/comfyanonymous/flux_text_encoders/resolve/main/clip_l.safetensors | head -1; curl -s -m 10 -I https://huggingface.co/Falconsai/nsfw_image_detection/resolve/main/config.json | head -1
echo "== sd help (flux opts)"; $N/bin/sd --help 2>&1 | grep -E -- "--diffusion-model|--vae|--clip_l|--t5xxl|--cfg-scale|--sampling-method|--steps|--diffusion-fa|--clip-on-cpu|--offload|--vae-on-cpu|--vae-tiling|-W|--guidance" | cut -c1-140
echo "== how imgsvc calls sd (chroma)"; grep -n -E "sd_binary|\"sd\"|--diffusion|chroma|t5xxl|vae" $N/agent/imgsvc*.py $N/agent/*img*.py 2>/dev/null | cut -c1-200 | head -15
echo "== python libs"; $N/venv/bin/python -c "import transformers,torch;print('tf',transformers.__version__,'torch',torch.__version__)"; $N/venv/bin/python -c "import PIL;print('PIL',PIL.__version__)"
echo "== gpu free"; nvidia-smi --query-gpu=memory.used,memory.total --format=csv,noheader
